<?php namespace App\Http\Resources\Ai; use Illuminate\Http\Resources\Json\JsonResource; class AiChatResponseResource extends JsonResource { public function toArray($request) { return [ "message" => new AiChatMessageResource($this["message"] ?? null), "intent" => $this["intent"] ?? null, "period" => $this["period"] ?? null, "results" => $this["results"] ?? null, "actions" => $this["actions"] ?? [] ]; } }